import{c as a,Q as t,j as n,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Vibe Coding is a Ticking Time Bomb","description":"","frontmatter":{"url":"https://x.com/akshay_pachaar/status/2067646389291725258","title":"Vibe Coding is a Ticking Time Bomb","author":"akshay_pachaar","archived":"2026-06-20T00:00:00.000Z","handle":"@akshay_pachaar","published":"2026-06-18T00:00:00.000Z","stats":"54 likes · 9 retweets · 93 bookmarks · 15463 views","tags":["vibe-coding","security","operational-safety","runtime-permissions","retool","sponsored"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-18-@akshay_pachaar-725258.md","filePath":"research/tweets/2026-06-18-@akshay_pachaar-725258.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-06-18-@akshay_pachaar-725258.md"};function i(r,e,l,d,p,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="vibe-coding-is-a-ticking-time-bomb-—-akshay-pachaar" tabindex="-1">Vibe Coding is a Ticking Time Bomb — @akshay_pachaar <a class="header-anchor" href="#vibe-coding-is-a-ticking-time-bomb-—-akshay-pachaar" aria-label="Permalink to &quot;Vibe Coding is a Ticking Time Bomb — @akshay_pachaar&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/akshay_pachaar/status/2067646389291725258" target="_blank" rel="noreferrer">https://x.com/akshay_pachaar/status/2067646389291725258</a><strong>作者</strong>：akshay_pachaar（@akshay_pachaar） <strong>發布日期</strong>：2026-06-18 <strong>收錄日期</strong>：2026-06-20 <strong>類型</strong>：Twitter Article <strong>統計</strong>：54 likes · 9 retweets · 93 bookmarks · 15463 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>When an AI agent deletes a production database, the model is almost never the weak link. This sounds counterintuitive, but the dangerous part is rarely the code the agent writes. Instead, it is what sits around that code, the access it inherits, and the boundary nobody put in front of it. [圖 1] A model will happily generate a button that issues account credits and never question who is allowed to click it, because authorization was never in the prompt. Today, let&#39;s look at this in action and the solution to avoid this in production.</p><h1 id="a-coding-agent-reasons-about-correctness-not-operational-safety" tabindex="-1">A coding agent reasons about correctness, not operational safety <a class="header-anchor" href="#a-coding-agent-reasons-about-correctness-not-operational-safety" aria-label="Permalink to &quot;A coding agent reasons about correctness, not operational safety&quot;">​</a></h1><p>A coding agent optimizes for whether the code works. But it has no signal for the runtime context around that code, i.e., who is calling it, whether they are allowed to, and what the blast radius is when a call is wrong. Those constraints live outside the prompt and the codebase, so they never reach the output. [圖 2] How bad a wrong call gets depends on what it does. For instance, a wrong read and a wrong write fail differently:</p><ul><li>An unauthorized SELECT exposes data that should have stayed private.</li><li>A write goes further. An UPDATE, INSERT, or DELETE changes the state of the business, and once it commits, there is no undo. A better model won&#39;t solve this problem. The agent only has the code in front of it, and identity, permissions, and logging live outside the code, in the system that runs it. It generates the operation and leaves out everything that governs it, whether the caller is who they claim, whether their role permits it, whether it should pause for a human, and whether it gets recorded. Let&#39;s actually look at this in action to understand better.</li></ul><h1 id="my-test-run" tabindex="-1">My test run <a class="header-anchor" href="#my-test-run" aria-label="Permalink to &quot;My test run&quot;">​</a></h1><p>I asked Claude Code to build a small internal support console with one button that issues an account credit. Here&#39;s the prompt:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build a polished React internal tool called &quot;Support Console&quot; using Vite. This is a</span></span>
<span class="line"><span>real, professional internal app, not a demo toy. Treat visual quality as a priority.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LAYOUT</span></span>
<span class="line"><span>- Fixed left sidebar (~240px): app name/logo mark at top, one active nav item</span></span>
<span class="line"><span>  &quot;Customers&quot;, subtle user avatar pinned at the bottom.</span></span>
<span class="line"><span>- Main area: a header row with the page title and a search input, then a customers</span></span>
<span class="line"><span>  table.</span></span>
<span class="line"><span>- Table columns: Customer (avatar initials + name + email stacked), Plan, Balance,</span></span>
<span class="line"><span>  Status. Row hover highlight, sortable headers, sticky header row.</span></span>
<span class="line"><span>- Clicking a row opens a right-side slide-over panel (~440px) over a dimmed backdrop:</span></span>
<span class="line"><span>  customer name + plan pill + a large current-balance figure at top, a list of recent</span></span>
<span class="line"><span>  orders (date, amount, status pill) below, and a primary &quot;Issue Credit&quot; button.</span></span>
<span class="line"><span>- &quot;Issue Credit&quot; opens a small form (amount field with a $ prefix, reason textarea,</span></span>
<span class="line"><span>  Confirm + Cancel). On confirm it updates the balance and fires a success toast.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>UI QUALITY (make it genuinely good)</span></span>
<span class="line"><span>- Aesthetic reference: Linear / Stripe dashboard / Retool. Calm, modern, restrained.</span></span>
<span class="line"><span>- Type: Inter or system stack. Clear scale: 13px body, 12px uppercase tracked labels,</span></span>
<span class="line"><span>  20px section headings. Use tabular figures for all currency.</span></span>
<span class="line"><span>- Color: neutral base (#fafafa app bg, #ffffff surfaces, #e5e7eb borders, #111827</span></span>
<span class="line"><span>  text, #6b7280 muted) with ONE accent (indigo ~#4f46e5) used only for primary</span></span>
<span class="line"><span>  actions and active states.</span></span>
<span class="line"><span>- Status pills with soft backgrounds: active/paid green, pending/past_due amber,</span></span>
<span class="line"><span>  failed/canceled red, free/neutral gray. Currency right-aligned.</span></span>
<span class="line"><span>- Components: 8px corner radius, subtle 1px borders over heavy shadows, focus rings</span></span>
<span class="line"><span>  on inputs, 150ms hover/transition. Primary and secondary button styles.</span></span>
<span class="line"><span>- States: loading skeletons for the table, an empty state for &quot;no results&quot;, and a</span></span>
<span class="line"><span>  disabled/spinner state on the Confirm button while submitting.</span></span>
<span class="line"><span>- No emojis, no gradients, no clutter. Whitespace and alignment over density.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DATA LAYER (critical for clean import into another platform later)</span></span>
<span class="line"><span>- Put ALL data access in a single module src/api.js with exactly these named async</span></span>
<span class="line"><span>  functions and nothing else: getCustomers(), getCustomer(id),</span></span>
<span class="line"><span>  issueCredit(customerId, amount, reason).</span></span>
<span class="line"><span>- Back them with realistic in-memory mock data: ~30 customers with varied names,</span></span>
<span class="line"><span>  plans, balances, statuses, and 3-6 orders each, so the app runs standalone now.</span></span>
<span class="line"><span>- issueCredit is the ONLY function that modifies data. Keep it isolated and obvious.</span></span>
<span class="line"><span>- Components must call ONLY these api.js functions, never inline fetches or mock data</span></span>
<span class="line"><span>  directly, so the data layer is a single clean seam.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Run it so I can click through and issue a credit end to end.</span></span></code></pre></div><p>It worked on the first run, and on my laptop, the credit was applied to the balance the instant I clicked: [圖 3 — 來源: First run] Issuing a credit is a write, an UPDATE that changes a balance, and a write like that is the kind of thing that commits permanently in production. In this case, the agent generated the code end-to-end and stopped. Any caller could reach it, and no role decided whether they were allowed, and nothing was recorded of what they did. Of course, it built exactly what I asked for. While the model knows well that a button moving money in production needs an access check, it just didn&#39;t add one because the prompt didn&#39;t ask it to.</p><h1 id="why-does-this-happen" tabindex="-1">Why does this happen? <a class="header-anchor" href="#why-does-this-happen" aria-label="Permalink to &quot;Why does this happen?&quot;">​</a></h1><p>In one widely-reported case, eleven ALL-CAPS warnings not to touch production did not stop an agent from deleting the database. [圖 4] Instructions live inside the same context that the model is free to override, so they are guidance, not enforcement. Ideally, these controls should live in the platform the app runs on, not in the app. Because the moment each app handles its own permissions, you get a hundred tools with a hundred different rules and no central way to manage them. That sprawl is what Shadow AI really means. The boundary should belong to the runtime where:</p><ul><li>Credentials are scoped server-side</li><li>Access runs through shared permission groups</li><li>And writes are gated and logged centrally. An agent can&#39;t emit that, because it lives outside the app it builds. Solving the problem is important because building software is now open to everyone. However, understanding how that software gets exposed is not. The people shipping these tools can&#39;t see the risk they&#39;re shipping, so the responsibility moves to engineers to build the infrastructure that supports them and also enforces safety underneath them automatically.</li></ul><h1 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;Solution&quot;">​</a></h1><p>The solution to this is now actually implemented in Retool, which is a platform for building and running internal tools, where every app automatically inherits your org&#39;s identity, access rules, and audit trail without extra setup. [圖 5] Essentially, instead of asking the model to add the boundary it was never going to add, you can keep building wherever you are fastest (Claude Code, Cursor, Codex, etc) and let the Retool runtime supply the boundary on the way to production. To demonstrate this, I took the same app from earlier and dropped its React bundle into Retool: [圖 6 — 來源: Run 2] Once done, it parsed the components, pulled them in, and walked me through pointing the app&#39;s data calls at a Retool resource, the governed connection that fronts the real database, everything automatically. I wrote none of the access control myself. Note: Setup-wise, I only signed up for Retool to get production infrastructure for the app. The React code was generated on its own, with no knowledge that Retool would later run it, which is the most important point here. Nothing in the build was written for Retool, and it still imported cleanly. That said, there&#39;s a Retool MCP server if you&#39;d rather have the runtime guide the build from inside your coding agent, but I didn&#39;t use it here. The import worked on a plain, Retool-unaware bundle. [圖 7] The moment those data calls ran through the resource, the app inherited identity, permissions, and an audit trail from the runtime. As depicted in the video above, the credit call was now routed through the resource layer. Moreover, SSO resolved the caller to a real identity. And permission groups decided whether their role can issue credit. The mutating query trips an approval gate that is on by default, so the write waits for a human instead of committing silently. Each run lands in an audit log with a name and a timestamp. Nothing in the app changed. It&#39;s the same credit button with the same function behind it. What changed is that the write now runs through Retool&#39;s boundary. [圖 8] An app sitting on real data has to resolve a stack of things the agent never reasons about during development:</p><ul><li>Which rows a given user can query?</li><li>Which columns should come back masked?</li><li>Should this action require an approver?</li><li>Whether a call can be resolved to an identity that can be traced back later? Retool handles all of that. You can build the app anywhere you like, in Claude Code, Cursor, or any agent, and push it to Retool&#39;s runtime, and the runtime automatically enforces identity, permissions, data access, approvals, and logging. The controls don&#39;t live in the code the agent wrote but directly in the environment it runs in, so they hold even when whoever built the app never knew to add them. You can try it out yourself here →</li></ul><hr><p>Thanks for reading, and to Retool for partnering on today&#39;s article.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Coding agents 優化 code 正確性，不優化 operational safety；identity/permissions/audit trail 在 prompt 和 codebase 之外，agent 無法生成這些邊界；文章透過 Retool（贊助商）展示將 runtime 安全邊界注入到 AI 生成 app 的路徑。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>Correctness vs Operational Safety 二分</strong>：agent 只能優化「code 能不能跑」，runtime context（誰在呼叫、有沒有權限、blast radius）在 prompt 之外，永遠不進輸出</li><li><strong>Write vs Read 風險不對稱</strong>：unauthorized SELECT 洩漏資料；UPDATE/INSERT/DELETE 改變業務狀態，提交後無 undo</li><li><strong>Instructions ≠ Enforcement</strong>：11 個 ALL-CAPS 警告無法阻止 agent 刪 production DB；prompt 內的指令和 context 同在，model 可 override；控制邊界需在執行環境層，不在 app 層</li><li><strong>Shadow AI 定義</strong>：每個 app 各自管自己的權限 → 百個工具百種規則無法集中管理 = Shadow AI 的真正含義</li><li><strong>Solution（Retool 廣告）</strong>：把 AI 生成的 React bundle 丟進 Retool runtime，自動繼承 org 的 SSO/permission groups/audit trail/approval gates</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>贊助披露：「Thanks to Retool for partnering on today&#39;s article」</li><li>支持 console demo：Claude Code 一次 pass，無 auth 控制，任何 caller 可達到</li><li>「widely-reported case」：11 個 ALL-CAPS 警告仍刪 production DB（未引用具體來源）</li><li>Retool 功能：SSO identity resolution / permission groups / write approval gate（default on）/ audit log with name + timestamp</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>贊助文章降低可信度</strong>：核心論點（agent 不做 security boundary）是正確且已知的；solution section = Retool 產品演示，不是中立分析</li><li><strong>核心原則不新鮮</strong>：「security 屬於 infrastructure 層，不屬於 app 層」是標準 enterprise architecture 原則；「AI 只做被問到的」也是已知 caveat</li><li><strong>「widely-reported case」無來源</strong>：11 ALL-CAPS 例子無法核查</li><li><strong>Demo 設計偏向結論</strong>：prompt 刻意不要求 auth（雖然這是真實狀況模擬），Retool import 過程細節省略</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>6/10</td><td>correctness vs operational safety 二分可作為 AI 建 production tool 的 checklist 項；但 solution 是付費產品廣告，無通用操作步驟</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>「AI 只建被問到的」是已知原則；runtime-vs-app boundary 是標準架構觀念；包裝有吸引力但無概念突破</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>自建 demo 真實，但贊助披露明顯；「11 ALL-CAPS」無來源；Retool import 細節省略</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>correctness/operational safety 二分論述清楚；SELECT vs write 風險非對稱分析具體；但技術細節集中在 Retool 功能演示</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>核心原則通用（AI-built tools 需 runtime-level security boundary）；Retool solution 不通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.60/10</strong></td><td>6×0.3+5×0.2+5×0.2+6×0.15+6×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：5.60 低於 6.0 閾值；主要降分因素是 Retool 贊助導致可信度下降（solution section = 廣告）、核心論點屬已知原則、證據品質偏弱。核心 insight（runtime-level security boundary）可從更中立的來源獲取。</p>`,33)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
